    const r = await whileWorking(t, 'Reading\u2026', () => api.pasteThread(S.storyId, text));
    if (!r) return;
    if (r.error) return toast(r.error);
    V = r.entries ? r : await api.story(S.storyId);
    const made = r.made ?? [];
